-- 遍历整张 VideoSubtitleVO, 按照 animeId 将 ids 装配进 SubtitleSegmentIds
function VideoSubtitleUtils.PrepareAllVOs()
    
    VideoSubtitleUtils.SubtitleSegmentIds = {}
    local allVOs = CfUtils.GetCf(AutoIds.IdSetting6040, "VideoSubtitleVO", true) -- VideoSubtitleVO
    for k,vo in pairs(allVOs) do 
        if isNull(VideoSubtitleUtils.SubtitleSegmentIds[vo.animeId]) then 
            VideoSubtitleUtils.SubtitleSegmentIds[vo.animeId] = {}
        end 
        table.insert( VideoSubtitleUtils.SubtitleSegmentIds[vo.animeId], vo.id )
    end
    -- debug:
    VideoSubtitleUtils.DebugSubtitleSegmentIds()
end


function VideoSubtitleUtils.DebugSubtitleSegmentIds()

    print("koko ------- 打印所有 视频字幕表 信息 (Begin) ---------:")
    for k,ids in pairs(VideoSubtitleUtils.SubtitleSegmentIds) do
        local str = "k: " .. tostring(k) 
        for m,id in pairs( ids ) do 
            str = str .. "\n    " .. tostring(id)
        end
        print(str)
    end
    print("koko ------- 打印所有 视频字幕表 信息 (End) ---------:")
end


-- 一次读取一段视频的所有 字幕段:
function VideoSubtitleUtils.ReadVideoSubtitleVO_ByAnimeId( animeId_ )
    if type(animeId_) ~= "string" then
        return nil
    end
    local ret = {}
    print("koko --0--")
    if isNotNull( VideoSubtitleUtils.SubtitleSegmentIds[animeId_] ) then 
        print("koko --1--")
        for k,id in pairs(VideoSubtitleUtils.SubtitleSegmentIds[animeId_]) do 
            print("koko --2--")
            local vo = CfUtils.GetCfVo(AutoIds.IdSetting6040, "VideoSubtitleVO", id) -- VideoSubtitleVO
            table.insert( ret, vo )
        end 
    end
    return ret
end



return VideoSubtitleUtils
